import numpy as np
import time

def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    # ||f*f||_2^2
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s*s*inf)

