            best = np.ones(50)
    else:
        best = np.ones(50)

    bestR = _R(best)
    N = len(best)
    rng = np.random.default_rng(12345)

    # Try a smooth "triangle-ish" bump of various widths as alternate starts.
    def make_bump(N, width):
        x = np.arange(N) - (N-1)/2.0
        return np.maximum(0.0, 1.0 - np.abs(x)/(width+1e-9))

    candidates = [best]
    for w in (N*0.25, N*0.35, N*0.45, N*0.6):
        candidates.append(make_bump(N, max(w,1.0)))
    # flat top with smooth edges (plateau) — converges toward constant
