                stall = 0
                if time.process_time() > deadline - 3.0:
                    break

    # ---- final high-beta polish ----
    if have_scipy and time.process_time() < deadline - 0.3:
        for beta in [1e6, 1e7, 1e8]:
            if time.process_time() >= deadline - 0.2:
                break
            hl, rl = run_lbfgs(best.copy(), maxiter=3000, ftol=1e-17, beta=beta)
            if hl is not None and rl > bestR:
                bestR = rl; best = hl.copy()

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    if best.size > 50000:
        best = best[:50000]
    return best

